{
  "action": "write_file",
  "path": "app.py",
  "content": "from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Optional, List

app = FastAPI()
todos = []
current_id = 1

class Todo(BaseModel):
    id: Optional[int] = None
    title: str

@app.get("/todos")
def get_todos():
    return todos

@app.post("/todos")
def create_todo(todo: Todo):
    global current_id
    todo.id = current_id
    todos.append(todo)
    current_id += 1
    return todo

@app.delete("/todos/{todo_id}")
def delete_todo(todo_id: int):
    global todos
    todo = next((t for t in todos if t.id == todo_id), None)
    if todo is None:
        raise HTTPException(status_code=404, detail="Todo not found")
    todos = [t for t in todos if t.id != todo_id]
    return None",
  "explanation": "This code sets up a FastAPI application with a list to store todos and a global counter for assigning unique IDs. It includes routes for getting all todos, creating a new todo, and deleting a todo by ID. The delete route checks if the todo exists before attempting to remove it, raising an HTTPException if not found."
}
```

